package com.ledgerx.application.ledger;
import java.util.*;
public final class RecordException extends Exception {private final int httpStatus;private final String code;private final Map<String,String> fieldErrors;private final Map<String,Object> details;public RecordException(int s,String c,String m){this(s,c,m,Collections.emptyMap(),Collections.emptyMap());}public RecordException(int s,String c,String m,Map<String,String>f,Map<String,Object>d){super(m);httpStatus=s;code=c;fieldErrors=Collections.unmodifiableMap(new LinkedHashMap<>(f));details=Collections.unmodifiableMap(new LinkedHashMap<>(d));}public int getHttpStatus(){return httpStatus;}public String getCode(){return code;}public Map<String,String>getFieldErrors(){return fieldErrors;}public Map<String,Object>getDetails(){return details;}}
